PROGRAM ST290_OVERLAMNING
VAR
    steg        : INT := 0;
    tmrHamta    : TON;
    tmrAck      : TON;
    tmrDone     : TON;
    xStopp      : BOOL := FALSE;
    xLarm       : BOOL := FALSE;
    xDriftsklar : BOOL := FALSE;
END_VAR

(* EMG_OK och AIR_OK kommer utifran och lases bara. Ett brutet nodstopp och
   ett tappat lufttryck latchas: att kretsen sluts igen eller att trycket
   kommer tillbaka ar inget startbesked (ISO 13850:2015 4.1.4 och
   IEC 60204-1:2016 9.2.3.4.2). Stationens signalkarta bar inget
   kvitteringsdon, sa kvittensen hor hemma utanfor den har logiken och den
   har logiken far aldrig ge sig sjalv ett startbesked. *)
IF NOT EMG_OK OR NOT AIR_OK THEN
    xStopp := TRUE;
END_IF;

xDriftsklar := EMG_OK AND AIR_OK AND NOT xStopp AND NOT xLarm;

(* Robotens hamtcykel. Takten ar 5,0 s per modul och handskakningen tar
   drygt 1,4 s av den, sa hamtningen far 3,5 s. *)
tmrHamta(IN := xDriftsklar AND steg = 0, PT := T#3500ms);

(* Tidsvakter pa de tva stallen dar handskakningen vantar pa motparten. En
   vantan utan tidsgrans ar den vanligaste missen i en overlamning: roboten
   star kvar med modulen och ingen far veta det. *)
tmrAck(IN := xDriftsklar AND steg = 1, PT := T#10s);
tmrDone(IN := xDriftsklar AND steg = 3, PT := T#10s);
IF tmrAck.Q OR tmrDone.Q THEN
    xLarm := TRUE;
    xDriftsklar := FALSE;
END_IF;

IF NOT xDriftsklar THEN
    (* Ingen overlamning utan nodstoppskrets och tryckluft. Griparen
       kommenderas till slutet lage sa modulen inte lamnas halvvags, och
       bandet star still sa ingenting dras undan under griparen. *)
    ST290_HS_REQ := FALSE;
    ST290_HS_RST := FALSE;
    ST290_GRP_OPEN := FALSE;
    ST300_CNV_RUN := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            (* Bandet gar och for undan foregaende modul medan roboten
               hamtar nasta. Begaran laggs forst nar mottagningslaget ar
               ledigt, alltsa nar reflexfotocellen ar fri, och bandet
               stannar i samma steg: bandet ska sta still nar det
               kvitterar. *)
            ST290_HS_RST := FALSE;
            ST290_GRP_OPEN := FALSE;
            ST300_CNV_RUN := TRUE;
            IF tmrHamta.Q AND NOT ST300_PEC_RCV THEN
                ST290_HS_REQ := TRUE;
                ST300_CNV_RUN := FALSE;
                steg := 1;
            END_IF;
        1:
            (* Steg 1 i handskakningen ligger. Griparen ror sig inte forran
               bandet kvitterat: att slappa pa den egna begaran ar att
               slappa mot ett lage ingen bekraftat ar ledigt. *)
            IF ST300_HS_ACK THEN
                ST290_GRP_OPEN := TRUE;
                steg := 2;
            END_IF;
        2:
            (* Griparen oppnar. Anslaget tar 0,35 s och bekraftas av
               ST290_GRP_OPENED; en oppning som raknas som klar redan pa
               kommandot slapper modulen innan backarna gatt isar. *)
            IF ST290_GRP_OPENED THEN
                steg := 3;
            END_IF;
        3:
            (* ST300_HS_DONE ar kvittot pa att fotocellen sett modulen i
               mottagningslaget. Forst da drar roboten undan griparen och
               nollstaller handskakningen. *)
            IF ST300_HS_DONE THEN
                ST290_GRP_OPEN := FALSE;
                ST290_HS_RST := TRUE;
                steg := 4;
            END_IF;
        4:
            (* Bandet far nollstalla sina bada signaler forst nu. Nar bade
               kvittensen och klarsignalen ar borta ar handskakningen
               nollstalld, och forst da far bandet ga. Roboten slapper sin
               begaran i samma steg, sa nasta modul aldrig arver den
               forras kvittens. *)
            IF NOT ST300_HS_ACK AND NOT ST300_HS_DONE THEN
                ST300_CNV_RUN := TRUE;
                ST290_HS_REQ := FALSE;
                ST290_HS_RST := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;
END_PROGRAM

