            (* Griparen oppnar. Anslaget tar 0,35 s och bekraftas av
               ST290_GRP_OPENED; en oppning som raknas som klar redan pa
               kommandot slapper modulen innan backarna gatt isar. *)
            IF ST290_GRP_OPENED THEN
                steg := 3;
            END_IF;
        3:
            (* ST300_HS_DONE ar kvittot pa att fotocellen sett modulen i
               mottagningslaget. Forst da drar roboten undan griparen och
               nollstaller handskakningen. *)
            IF ST300_HS_DONE THEN
                ST290_GRP_OPEN := FALSE;
                ST300_CNV_RUN := FALSE;
                ST290_HS_RST := TRUE;
                steg := 4;
            END_IF;
        4:
            (* Bandet far nollstalla sina bada signaler forst nu. Nar bade
               kvittensen och klarsignalen ar borta ar handskakningen
               nollstalld, och forst da far bandet ga. Roboten slapper sin
               begaran i samma steg, sa nasta modul aldrig arver den
               forras kvittens. *)
            IF NOT ST300_HS_ACK AND NOT ST300_HS_DONE THEN
                ST300_CNV_RUN := TRUE;
                ST290_HS_REQ := FALSE;
                ST290_HS_RST := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;
END_PROGRAM
